/**
 * Catálogo de **utilería de fiesta** de la tienda de Sempertex (https://sempertex.com): lo que no es globo y acompaña
 * un montaje (banderines, platos, vasos, servilletas, manteles, bolsas de dulces…). Solo texto: nombre exacto en la
 * tienda, url relativa del producto, tipo, temática, colores y medidas cuando la tienda las da. Sin imágenes.
 *
 * Revisado el 2026-10-07 con el JSON público de la tienda (/products.json y /collections/<handle>/products.json): de
 * 1661 productos, 620 son utilería de fiesta (no globos). Colecciones de donde salen: decoracion-visual-halloween,
 * decoracion-accesorios-halloween, decoracion-mesa-halloween, desechables-fiesta-halloween, deluxe-halloween,
 * happy-halloween, temporada-halloween, mesa-halloween-showroom, decoracion-fiesta-fantasmitas, platos-, vasos-,
 * servilletas- y manteles-desechables-para-fiesta, banderolas-decorativas-fiestas, carteles-decorativos-fiestas,
 * sempertinas-decorativas-fiesta, velas-y-accesorios-cumpleanos, bolsas-de-dulces y tiaras-para-fiesta. La tienda no
 * vende piñatas ni popotes. Primero los de Halloween (y los lisos que la tienda agrupa con Halloween) y luego el resto,
 * por tipo. Los colores marcados «(por icono)» se dedujeron del dibujo del producto (la tienda no los da).
 *
 * `id` es el handle del producto en la tienda. Las piezas 3D de `utileria.ts` apuntan a estos productos por `id`; si
 * no hay uno igual, la pieza sale como «genérico».
 */
export type TipoUtileria =
  | "banderin" | "plato" | "vaso" | "servilleta" | "mantel" | "cubiertos" | "bolsa_dulces" | "calabaza_dulces" | "gorrito"
  | "letrero" | "topper" | "vela" | "caja_regalo" | "bandeja" | "paquete" | "pinata" | "popote" | "otro";

export type ProductoCatalogo = {
  /** Clave corta para referirse a él desde el código. */
  id: string;
  /** Nombre exacto, como sale en la tienda. */
  nombre: string;
  /** Url relativa de la tienda (/products/…). */
  url: string;
  tipo: TipoUtileria;
  tematica: string;
  colores: string[];
  /** Medidas o contenido tal como los da la tienda (null si no los da). */
  medidas: string | null;
  piezasPorPaquete: number | null;
};

export const TIENDA_SEMPERTEX = "https://sempertex.com";

