export function productoCatalogo(id: string): ProductoCatalogo | undefined {
  return CATALOGO_UTILERIA.find((p) => p.id === id);
}

/** La dirección completa de un producto en la tienda. */
export const urlTienda = (url: string): string => (url.startsWith("http") ? url : `${TIENDA_SEMPERTEX}${url}`);
